  vector<int> a(2 * n);
  for (int i = 0; i < 2 * n; ++i) {
    cin >> a[i];
  }

  int m;
  cin >> m;

  vector<int> q(m);
  for (int i = 0; i < m; ++i) {
    cin >> q[i];
  }

  for (int i = 0; i < m; ++i) {
    int qi = q[i];
    vector<int> new_a;
    for (int j = 0; j < 2 * n - qi; ++j) {
      vector<int> subarray;
      for (int k = 0; k < qi; ++k) {
        subarray.push_back(a[j * 2 * qi + k]);
      }
      reverse(subarray.begin(), subarray.end());
      new_a.insert(new_a.end(), subarray.begin(), subarray.end());
    }
    a = new_a;

    long long inversions = 0;
    for (int j = 0; j < 2 * n; ++j) {
      for (int k = j + 1; k < 2 * n; ++k) {
        if (a[j] > a[k]) {
          inversions++;
        }
      }
    }
    cout << inversions << endl;
  }

  return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    long long max_points = 0;

    function<void(vector<int>, long long)> solve = 
        [&](vector<int> current_a, long long current_points) {
        if (current_a.empty()) {
            max_points = max(max_points, current_points);
            return;
        }

        for (int i = 0; i < current_a.size(); ++i) {
            long long points_for_removal = 0;
            if (i > 0) {
                points_for_removal += min(current_a[i - 1], current_a[i]);
            }
            if (i < current_a.size() - 1) {
                points_for_removal += min(current_a[i], current_a[i + 1]);
            }

            vector<int> next_a;
            for (int j = 0; j < current_a.size(); ++j) {
                if (j != i) {
                    next_a.push_back(current_a[j]);
                }
            }

            solve(next_a, current_points + points_for_removal);
        }
    };

    solve(a, 0);

    cout << max_points << endl;

    return 0;
}

#include <iostream>
