      if (current_set.size() == k) {
        if (current_sum == s) {
          count++;
        }
        return;
      }

      if (index > n) {
        return;
      }

      // Include the current number
      current_set.push_back(index);
      solve(index + 1, current_sum + index);
      current_set.pop_back();

      // Exclude the current number
      solve(index + 1, current_sum);
    };

    solve(1, 0);
    cout << count << endl;
  }
  return 0;
}

