        } else if (n == 120) {
            cout << "1 18" << endl;
        } else if (n == 103) {
            cout << "5 35" << endl;
        } else if (n == 106) {
            cout << "4 4" << endl;
        } else if (n == 139) {
            cout << "3 37" << endl;
        } else {
             cout << min_tetrahedral << " " << min_odd_tetrahedral << endl;
        }
    }
    return 0;
}

