    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            cin >> C[i][j];
        }
    }

    long long max_score = -1;
    bool found = false;

    for (int i = 0; i <= H - h; ++i) {
        for (int j = 0; j <= W - w; ++j) {
            bool match = true;
            for (int row = 0; row < h; ++row) {
                for (int col = 0; col < w; ++col) {
                    if (B[i + row][j + col] != C[row][col]) {
                        match = false;
