    }

    int best_x = -1;
    int best_yl = -1;
    int best_yr = -1;
    long long min_remoteness = -1;

    for (int x = 1; x <= k; ++x) {
      for (int yl = 1; yl <= k - mi + 1; ++yl) {
        int yr = yl + mi - 1;
        long long remoteness = 0;

        int center_row = (k + 1) / 2;
        int center_seat = (k + 1) / 2;

        for (int j = yl; j <= yr; ++j) {
          remoteness += abs(x - center_row) + abs(j - center_seat);
        }

