          min_remoteness = remoteness;
          best_x = x;
          best_yl = yl;
          best_yr = yr;
        } else if (remoteness == min_remoteness) {
          if (x < best_x) {
            best_x = x;
            best_yl = yl;
            best_yr = yr;
          } else if (x == best_x && yl < best_yl) {
            best_x = x;
