                        for (int i = 0; i < cycle.size(); ++i) {
                            cout << cycle[i] << (i == cycle.size() - 1 ? "" : " ");
                        }
                        cout << endl;
                        return true;
                    }
                }
            } else {
                if (dfs(v, u)) return true;
            }
        }

        path.pop_back();
        return false;
    };

    for (int i = 1; i <= n; ++i) {
        if (!visited[i]) {
            if (dfs(i, -1)) break;
        }
    }

    return 0;
}

